        }

        internal static Probe Create(NeoClient client, NeoMemberClass node)
        {
            return NeoGeneratedTypesSupport.GetOrCreateGeneratedClassValue<Probe>(client, node, static (factoryClient, factoryNode) =>
            {
                var clientClassId = factoryNode.ClassId;
                return clientClassId switch
                {
                    _ => new Probe(factoryClient, factoryNode, true, NeoValueOwnership.Asset),
                };
            });
        }

        internal static Probe CreateWritable(NeoClient client, NeoMemberClassWritable node)
        {
            return NeoGeneratedTypesSupport.GetOrCreateGeneratedClassValue<Probe>(client, node, static (factoryClient, factoryNode) =>
            {
                var clientClassId = factoryNode.ClassId;
                return clientClassId switch
                {
                    _ => new Probe(factoryClient, factoryNode, false, factoryNode.ownership),
                };
            });
        }

        internal static Probe? CreateDetached(NeoClient client, NeoDetachedValue value, bool saved)
        {
            return new Probe(client, value, !saved);
        }

        public Probe Clone()
        {
            return CreateWritable(client, NeoGeneratedTypesSupport.CloneClassValue(client, this));
        }

        IReadOnlyProbe IReadOnlyProbe.Clone()
        {
            return Clone();
        }

